"""Migrated invoiced-order workflow, validation, and total recomputation rules."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    """Raised when an order operation violates a business rule."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


_CENTS = Decimal("0.01")


def _decimal(value: Any, default: Any = 0) -> Decimal:
    """Apply legacy NVL-like numeric conversion."""
    if value is None or value == "":
        value = default
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply the allowed status behavior for an invoiced order."""
    if order["STAT_CD"] != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = order.copy()

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated_order, [], []

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and the discounted order total."""
    updated_order = order.copy()
    updated_lines = [line.copy() for line in lines]

    if order["STAT_CD"] in {"I", "X"}:
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG", "") == "Y":
            continue

        extension = _round_cents(
            _decimal(line.get("QTY", 0)) * _decimal(line.get("UNIT_PRC", 0))
        )
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _round_cents(
        total * (Decimal("100") - _decimal(order.get("DISC_PCT", 0))) / Decimal("100")
    )
    stored_total = _decimal(order.get("TOT_AMT", 0))

    updated_order["TOT_AMT"] = float(discounted_total)
    audits = ["ORD_RETOTAL"] if discounted_total != stored_total else []

    return updated_order, updated_lines, audits
